"""adstyles15 - "10 AI ad styles" listicle (Jan, 2026-11-09). Real outputs: 10 images generated by Nano Banana 2.1 on Higgsfield
(Jan's account, prompts in prompts.md, job ids in jobs.json). Fictional products/brands (NOVA, SOL, VOLT), no real logos.
Higgsfield is credited as plain text only (no logo without permission). Music + subtle sfx, no voice. 9:16, ~18.5 s."""
import json, shutil, subprocess, sys
from pathlib import Path
HERE = Path(__file__).parent
H = HERE.parent.parent
sys.path.insert(0, str(H))
from house import write_sfx

W = H / "work" / "adstyles15"; A = W / "assets"
A.mkdir(parents=True, exist_ok=True); (W / "renders").mkdir(exist_ok=True)
for f in (H / "template").iterdir():
    shutil.copy(f, W / f.name)
for f in (H / "assets").iterdir():
    shutil.copy(f, A / f.name)
for f in (HERE / "media").iterdir():
    shutil.copy(f, A / f.name)

STYLES = [  # file, style, product
    ("s_volt.jpg", "Giant Product", "energy drink"),
    ("s_sol.jpg", "Splash Shot", "orange juice"),
    ("s_head.jpg", "Exploded View", "headphones"),
    ("s_watch.jpg", "Frozen in Ice", "smartwatch"),
    ("s_latte.jpg", "Miniature World", "latte"),
    ("s_pad.jpg", "Neon Night", "game controller"),
    ("s_shoe.jpg", "Levitation", "sneaker"),
    ("s_lips.jpg", "Macro Detail", "lipstick"),
    ("s_clay.jpg", "Clay World", "instant camera"),
    ("s_nova.jpg", "Minimal Studio", "perfume"),
]
T0, STEP = 0.55, 1.45
END = round(T0 + STEP * len(STYLES), 2)
DUR = round(END + 3.3, 2)

TR = "t1"
start = json.load(open(H.parent / "video/public/music/tracks.json"))[TR]["hook_start"]
subprocess.run(["ffmpeg", "-v", "error", "-y", "-ss", str(start), "-i", str(H.parent / f"video/public/music/{TR}.mp3"), "-t", str(DUR + 1),
                "-af", f"afade=t=in:d=0.3,afade=t=out:st={DUR - 0.8}:d=0.8", str(A / "music.mp3")], check=True)
ev = [(0.0, "whoosh")]
for i in range(len(STYLES)):
    t = T0 + i * STEP
    if i: ev.append((t, "whoosh"))
    ev.append((t + 0.08, "pop")); ev.append((t + 0.35, "click"))
ev += [(END, "whoosh"), (END + 0.35, "pop")]
write_sfx(ev, DUR, A / "sfx.wav")

LOGO = (HERE / "media" / "higgsfield_logo.png").exists()
HF = '<img class="hl" src="assets/higgsfield_logo.png" alt=""><b class="hn">Higgsfield</b>' if LOGO else 'Higgsfield'
rows = "".join(f'<div class="row" id="r{i}"><span class="n">{i + 1:02d}</span><span class="t">{s}</span></div>' for i, (_, s, _) in enumerate(STYLES))
cards = "".join(f'<div class="card" id="c{i}"><img src="assets/{f}" alt=""></div>' for i, (f, _, _) in enumerate(STYLES))
names = "".join(f'<div class="nm" id="n{i}"><b>{s}</b><span>{p}</span></div>' for i, (_, s, p) in enumerate(STYLES))
thumbs = "".join(f'<div class="th" id="t{i}" style="left:{70 + (i % 5) * 192}px;top:{760 + (i // 5) * 252}px"><img src="assets/{f}" alt=""></div>' for i, (f, _, _) in enumerate(STYLES))

HTML = f'''<!doctype html><html lang="en" data-resolution="portrait"><head><meta charset="UTF-8"><meta name="viewport" content="width=1080, height=1920"><script src="assets/gsap.min.js"></script><style>
*{{margin:0;padding:0;box-sizing:border-box}}
html,body{{width:1080px;height:1920px;overflow:hidden;background:#0c0c0e}}
#root{{position:relative;width:1080px;height:1920px;overflow:hidden;font-family:'Inter',sans-serif;color:#fff;background:radial-gradient(90% 60% at 60% 38%,#1d1b22 0%,#0c0c0e 70%)}}
#grain{{position:absolute;left:-256px;top:-256px;width:1592px;height:2432px;opacity:.05;mix-blend-mode:screen;background:url(assets/noise.png) repeat}}
#glow{{position:absolute;left:300px;top:260px;width:780px;height:1000px;border-radius:50%;filter:blur(120px);opacity:.55}}
#top{{position:absolute;left:70px;right:70px;top:150px}}
#top .k{{display:inline-block;font-family:'JetBrains Mono',monospace;font-size:26px;color:#ff4b1f;background:rgba(255,75,31,.12);border:1.5px solid rgba(255,75,31,.45);padding:6px 16px;border-radius:30px;letter-spacing:.06em}}
#top h1{{font-size:86px;font-weight:900;letter-spacing:-.035em;line-height:1;margin-top:18px}}
#top h1 i{{font-family:'EB Garamond',serif;font-weight:500;font-style:italic;color:#ff4b1f;letter-spacing:-.01em}}
.row{{position:absolute;left:70px;width:270px;height:56px;display:flex;align-items:center;gap:14px;font-size:27px;font-weight:600;color:rgba(255,255,255,.32);border-radius:14px;padding-left:12px}}
.row .n{{font-family:'JetBrains Mono',monospace;font-size:22px;color:rgba(255,255,255,.28)}}
.row.on{{color:#111;background:#fff}} .row.on .n{{color:#ff4b1f}}
.row.done{{color:rgba(255,255,255,.62)}} .row.done .n{{color:#ff4b1f}}
.card{{position:absolute;left:370px;top:450px;width:640px;height:800px;border-radius:34px;overflow:hidden;box-shadow:0 40px 90px rgba(0,0,0,.65),0 0 0 1.5px rgba(255,255,255,.08);opacity:0}}
.card img{{width:100%;height:100%;object-fit:cover;transform-origin:50% 55%}}
.nm{{position:absolute;left:370px;top:1272px;width:640px;opacity:0}}
.nm b{{display:block;font-size:56px;font-weight:800;letter-spacing:-.02em}}
.nm span{{display:block;font-family:'EB Garamond',serif;font-style:italic;font-size:38px;color:rgba(255,255,255,.6);margin-top:2px}}
#tool{{position:absolute;left:370px;top:1410px;display:flex;align-items:center;gap:10px;font-size:26px;font-weight:600;color:rgba(255,255,255,.85);background:rgba(255,255,255,.08);border:1.5px solid rgba(255,255,255,.16);padding:10px 20px;border-radius:30px}}
#tool b{{color:#c8ff3d}} .hl{{height:36px;border-radius:9px;vertical-align:middle}} .hn{{color:#fff!important}} #end .tl{{display:flex;justify-content:center;align-items:center;gap:12px}} #end .tl .hl{{height:56px;border-radius:13px}}
#handle{{position:absolute;left:50%;top:1560px;transform:translateX(-50%);background:#ff4b1f;color:#fff;font-weight:700;font-size:34px;padding:12px 34px;border-radius:40px;box-shadow:0 10px 30px rgba(255,75,31,.35)}}
#end{{position:absolute;inset:0;background:#0c0c0e;opacity:0}}
#end .c{{position:absolute;left:0;right:0;top:300px;text-align:center;font-weight:800;font-size:92px}}
#end .kw{{position:absolute;left:0;right:0;top:405px;text-align:center;font-weight:900;font-size:150px;color:#ff4b1f;letter-spacing:-.04em}}
#end .g{{position:absolute;left:0;right:0;top:600px;text-align:center;font-weight:800;font-size:50px}}
.th{{position:absolute;width:172px;height:215px;border-radius:18px;overflow:hidden;box-shadow:0 20px 40px rgba(0,0,0,.6);opacity:0}}
.th img{{width:100%;height:100%;object-fit:cover}}
#end .tl{{position:absolute;left:0;right:0;top:1300px;text-align:center;font-size:30px;font-weight:600;color:rgba(255,255,255,.8)}}
#end .tl b{{color:#c8ff3d}}
#end .fo{{position:absolute;left:0;right:0;top:1380px;text-align:center;font-size:36px;font-weight:700}}
</style></head><body>
<div id="root" data-composition-id="main" data-start="0" data-duration="{DUR}" data-width="1080" data-height="1920" data-motion-blur="off">
<div id="glow"></div>
<div id="top"><span class="k">AI AD STYLES</span><h1>10 ad styles <i>brands</i><br>actually pay for</h1></div>
{rows}{cards}{names}
<div id="tool">Made with <b>Nano Banana</b> · {HF}</div>
<div id="end"><div class="c">Comment</div><div class="kw">“STYLES”</div><div class="g">and I'll send you all 10 prompts</div>{thumbs}
<div class="tl">All 10 made with <b>Nano Banana</b> · {HF}</div><div class="fo">Follow for more AI tools</div></div>
<div id="handle">@theaitoolfinds</div>
<div id="grain"></div>
<audio id="mus" class="clip" src="assets/music.mp3" data-start="0" data-duration="{DUR}" data-track-index="21" data-volume="0.32"></audio>
<audio id="fx" class="clip" src="assets/sfx.wav" data-start="0" data-duration="{DUR}" data-track-index="22" data-volume="0.9"></audio>
</div>
<script>
window.__timelines=window.__timelines||{{}};
const N={len(STYLES)}, T0={T0}, ST={STEP}, END={END}, DUR={DUR};
const GL=['#ff8a2a','#ffb02a','#7a8cff','#5ad0ff','#d79a5a','#ff3ab0','#ff7a5a','#ff4a6a','#7ae0c0','#b7c9a0'];
const tl=gsap.timeline({{paused:true}}); const NI={{immediateRender:false}};
function F(s,a,b,t){{ return tl.fromTo(s,a,Object.assign({{}},b,NI),t); }}
for(let i=0;i<N;i++) tl.set('#r'+i,{{top:440+i*66}},0);
tl.set('.card',{{opacity:0}},0); tl.set('.nm',{{opacity:0}},0); tl.set('#end',{{opacity:0}},0); tl.set('.th',{{opacity:0}},0);
// hook: title + first card already on screen at t=0
F('#top',{{opacity:0,y:30}},{{opacity:1,y:0,duration:.45,ease:'expo.out'}},0);
F('.row',{{opacity:0,x:-30}},{{opacity:1,x:0,duration:.4,ease:'expo.out',stagger:.025}},0.05);
for(let i=0;i<N;i++){{
  const t=T0+i*ST, c='#c'+i, nm='#n'+i, r='#r'+i;
  const tin = i===0 ? 0 : t;
  F(c,{{opacity:0,y:140,scale:.9,rotation:i%2?2.5:-2.5}},{{opacity:1,y:0,scale:1,rotation:0,duration:.55,ease:'expo.out'}},tin);
  F(c+' img',{{scale:1.12}},{{scale:1.0,duration:ST+.6,ease:'none'}},tin);
  F(nm,{{opacity:0,y:24}},{{opacity:1,y:0,duration:.35,ease:'expo.out'}},Math.max(tin,t)+0.1);
  tl.set(r,{{className:'row on'}},i===0?0:t);
  tl.set('#glow',{{background:GL[i]}},i===0?0:t);
  if(i<N-1){{ const t2=t+ST; F(c,{{opacity:1,y:0,scale:1,filter:'blur(0px)'}},{{opacity:0,y:-120,scale:.94,filter:'blur(14px)',duration:.32,ease:'power3.in'}},t2-0.12);
    F(nm,{{opacity:1}},{{opacity:0,duration:.15}},t2-0.12); tl.set(r,{{className:'row done'}},t2); }}
}}
F('#glow',{{opacity:.35}},{{opacity:.6,duration:1.2,yoyo:true,repeat:Math.ceil(DUR/1.2)}},0);
tl.set(['#c'+(N-1),'#n'+(N-1)],{{opacity:0}},END+0.3);
F('#end',{{opacity:0}},{{opacity:1,duration:.3,ease:'none'}},END);
F('#end .c',{{opacity:0,y:40}},{{opacity:1,y:0,duration:.4,ease:'expo.out'}},END+0.05);
F('#end .kw',{{opacity:0,scale:1.5}},{{opacity:1,scale:1,duration:.45,ease:'back.out(1.8)'}},END+0.15);
F('#end .g',{{opacity:0,y:30}},{{opacity:1,y:0,duration:.4,ease:'expo.out'}},END+0.3);
for(let i=0;i<N;i++) F('#t'+i,{{opacity:0,y:120,rotation:(i%2?6:-6)}},{{opacity:1,y:0,rotation:(i%2?2:-2),duration:.5,ease:'back.out(1.5)'}},END+0.35+i*0.04);
F('#end .tl',{{opacity:0}},{{opacity:1,duration:.3}},END+0.8);
F('#end .fo',{{opacity:0,y:20}},{{opacity:1,y:0,duration:.35,ease:'expo.out'}},END+0.95);
tl.set('#tool',{{opacity:0}},END);
for(let k=0,t=0;t<DUR;k++,t=k/12){{ const sd=(k*7919)%997; tl.set('#grain',{{x:-(sd%256),y:-((sd*31)%256)}},t); }}
window.__timelines['main']=tl; tl.seek(0);
</script></body></html>'''
(W / "index.html").write_text(HTML)
print("ok adstyles15 dur", DUR, "end", END)
